package com.englishhero.practice.review;
import com.sun.net.httpserver.HttpServer;
import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.Test;import tools.jackson.databind.ObjectMapper;
import static org.assertj.core.api.Assertions.*;
class DeepSeekSelectionClientTest {
 @Test void translatesOnlySelectionWithBoundedOutputAndTrustedUsage()throws Exception{var json=new ObjectMapper();var sent=new AtomicReference<String>();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/chat/completions",e->{sent.set(new String(e.getRequestBody().readAllBytes(),StandardCharsets.UTF_8));byte[] response=json.writeValueAsBytes(Map.of("model","deepseek-flash","choices",List.of(Map.of("finish_reason","stop","message",Map.of("content","{\"translation\":\"当奥马尔搬到新城镇时\"}"))),"usage",Map.of("prompt_tokens",200,"completion_tokens",20)));e.sendResponseHeaders(200,response.length);e.getResponseBody().write(response);e.close();});server.start();try{var config=new PracticeReviewProperties();config.setEnabled(true);config.setApiKey("synthetic-only");var client=new DeepSeekReviewClient(config,json,new PracticeReviewResultValidator(json),URI.create("http://127.0.0.1:"+server.getAddress().getPort()+"/chat/completions"));var result=client.getClass().getMethod("translate",String.class).invoke(client,"When Omar moved to a new town");assertThat(result.getClass().getMethod("translation").invoke(result)).isEqualTo("当奥马尔搬到新城镇时");var body=json.readTree(sent.get());assertThat(body.get("max_tokens").asInt()).isEqualTo(1024);assertThat(sent.get()).doesNotContain("userId","articleId","password");assertThat(body.at("/thinking/type").asText()).isEqualTo("disabled");}finally{server.stop(0);}}
}
